CREATE OR REPLACE FUNCTION public.combat_v2_autopick_choose(p_cs jsonb, p_score jsonb, p_cap integer, p_pick jsonb)
 RETURNS integer[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare att integer[]; ats numeric[]; sup integer[]; sus numeric[]; lo int; hi int; ns int; na int;
begin
